/**
 * Anchor integration tests for programs/flacon (briefing §6, tests a–g, plus the hardening cases:
 * freshness / revocation of server keys, Ed25519 instruction placement, sticky grades, seal limits,
 * issuer-only seal administration, partner removal, authority transfer, Core asset validation).
 * Runs against the local validator started by `anchor test`.
 *
 * Fixtures: docs/vectors.json and docs/enums.json (generated by packages/proof — never edited here).
 * The vector signatures carry fixed timestamps (2026-09), which the program now rejects as stale; the
 * happy paths therefore re-sign the same fields with a fresh ts under the same test key.
 */
import * as anchor from "@anchor-lang/core";
import { BN, Program } from "@anchor-lang/core";
import {
  ComputeBudgetProgram,
  Ed25519Program,
  Keypair,
  LAMPORTS_PER_SOL,
  PublicKey,
  SYSVAR_INSTRUCTIONS_PUBKEY,
  SYSVAR_RENT_PUBKEY,
  SystemProgram,
  TransactionInstruction,
} from "@solana/web3.js";
import { expect } from "chai";
import * as fs from "fs";
import * as path from "path";
import nacl from "tweetnacl";
import type { Flacon } from "../target/types/flacon";
import {
  ROOT,
  SEEDS,
  SITE_1,
  SITE_2,
  airdrop,
  buildScanMessage,
  bytes,
  chainTime,
  createCoreAsset,
  ed25519Ix,
  ensureRegistry,
  enums,
  expectAnchorError,
  heatMask,
  hex,
  label32,
  mintPassportWithSeal,
  recordScan,
  recordScanBuilder as buildScan,
  scanArgs,
  scanPdaOf,
  sealPdaOf,
  serverKp,
  serverPubkey,
  sha256,
  signMessage,
  vectors,
  type RegistryHandle,
} from "./lib/flacon";

const MSG_PREFIX: string = vectors.constants.MSG_PREFIX;
const MSG_LEN: number = vectors.constants.MSG_LEN;

type ScanInput = {
  serial: string;
  uidHex: string;
  counter: number;
  tier: number;
  role: number;
  tamper: number;
  uv: number;
  hum: number;
  heat: number;
  heatLevels: number[];
  fill: number;
  mediaHashHex: string;
  nonceHex: string;
  ts: number;
};
type ScanVector = {
  name: string;
  input: ScanInput;
  serialHashHex: string;
  uidHashHex: string;
  heatMask: number;
  msgHex: string;
  sigHex: string;
  grade: number;
  bundleHashHex: string;
};
const scans: ScanVector[] = vectors.scans;
const scan0 = scans[0];

// §4.5 grade rule in TS (same rule as packages/proof/src/grade.ts)
const G = enums.grade as Record<string, number>;
const I = enums.indicator as Record<string, number>;
const T = enums.tamper as Record<string, number>;
const FILL_A_MIN = 90;
const FILL_B_MIN = 60;
function gradeRule(i: {
  verdict?: string;
  sealDead?: boolean;
  tamper: number;
  heat: number;
  hum: number;
  fill: number;
}): number {
  if ((i.verdict ?? "VALID") !== "VALID" || i.sealDead) return G.VOID;
  if (i.tamper === T.OPENED_NOW || i.tamper === T.OPENED_BEFORE) return G.VOID;
  if (i.heat === I.TRIGGERED || i.hum === I.TRIGGERED) return G.C;
  if (i.fill >= FILL_A_MIN) return G.A;
  if (i.fill >= FILL_B_MIN) return G.B;
  return G.D;
}

describe("flacon", () => {
  const provider = anchor.AnchorProvider.env();
  anchor.setProvider(provider);
  const program = anchor.workspace.flacon as Program<Flacon>;
  const wallet = provider.wallet.publicKey;
  const idlErrors = (program.idl.errors ?? []) as { code: number; name: string }[];

  const [registryPda] = PublicKey.findProgramAddressSync([Buffer.from(SEEDS.registry)], program.programId);
  let SERVER_KEY_ID = vectors.serverTestKey.keyId as number;
  const serialHash = hex(scan0.serialHashHex);
  const uidHash = hex(scan0.uidHashHex);
  const bindingHash = hex(vectors.hashes.binding[0].sha256Hex);
  const [passportPda] = PublicKey.findProgramAddressSync([Buffer.from(SEEDS.passport), serialHash], program.programId);
  const [sealPda] = PublicKey.findProgramAddressSync([Buffer.from(SEEDS.seal), uidHash], program.programId);
  const scanPda = (counter: number) => {
    const c = Buffer.alloc(4);
    c.writeUInt32LE(counter);
    return PublicKey.findProgramAddressSync([Buffer.from(SEEDS.scan), sealPda.toBuffer(), c], program.programId)[0];
  };
  let asset: PublicKey; // a real Metaplex Core asset (created in "(a) mint passport")
  const now = () => Math.floor(Date.now() / 1000);

  /** record_scan args from a vector input (heat_levels as 6-bit mask). */
  function argsFrom(v: ScanVector, overrides: Partial<Record<string, any>> = {}) {
    const i = v.input;
    return {
      counter: i.counter,
      tier: i.tier,
      role: i.role,
      tamper: i.tamper,
      uv: i.uv,
      hum: i.hum,
      heat: i.heat,
      heatLevels: heatMask(i.heatLevels),
      fill: i.fill,
      siteId: 0,
      mediaHash: bytes(hex(i.mediaHashHex)),
      bundleHash: bytes(hex(v.bundleHashHex)),
      nonce: bytes(hex(i.nonceHex)),
      ts: new BN(i.ts),
      serverKeyId: SERVER_KEY_ID,
      ...overrides,
    };
  }
  /** Message for a given args object, bound to the test passport/seal. */
  function msgFor(a: ReturnType<typeof argsFrom>): Buffer {
    return buildScanMessage({
      serialHash,
      uidHash,
      counter: a.counter,
      tamper: a.tamper,
      uv: a.uv,
      hum: a.hum,
      heat: a.heat,
      fill: a.fill,
      mediaHash: Buffer.from(a.mediaHash),
      nonce: Buffer.from(a.nonce),
      ts: BigInt(a.ts.toString()),
    });
  }
  function recordScanBuilder(a: ReturnType<typeof argsFrom>, attester: PublicKey = wallet) {
    return program.methods.recordScan(a).accountsStrict({
      registry: registryPda,
      passport: passportPda,
      seal: sealPda,
      scanProof: scanPda(a.counter),
      attester,
      instructions: SYSVAR_INSTRUCTIONS_PUBKEY,
      systemProgram: SystemProgram.programId,
    });
  }

  // -------------------------------------------------------------------------

  it("TS message builder reproduces vectors.scans[*].msgHex and the signatures verify", () => {
    for (const s of scans) {
      const i = s.input;
      const m = buildScanMessage({
        serialHash: hex(s.serialHashHex),
        uidHash: hex(s.uidHashHex),
        counter: i.counter,
        tamper: i.tamper,
        uv: i.uv,
        hum: i.hum,
        heat: i.heat,
        fill: i.fill,
        mediaHash: hex(i.mediaHashHex),
        nonce: hex(i.nonceHex),
        ts: i.ts,
      });
      expect(m.toString("hex"), s.name).to.equal(s.msgHex);
      expect(nacl.sign.detached.verify(m, hex(s.sigHex), serverPubkey), `${s.name} sig`).to.be.true;
      expect(heatMask(i.heatLevels), `${s.name} heatMask`).to.equal(s.heatMask);
    }
    expect(Buffer.from(serverKp.publicKey).toString("hex")).to.equal(vectors.serverTestKey.pubkeyHex);
  });

  it("(a) init registry, server key, partner, 2 sites", async () => {
    // idempotent: tests/escrow.ts (runs first alphabetically) may already have set this up identically
    const h = await ensureRegistry(program, wallet);
    SERVER_KEY_ID = h.serverKeyId;
    const reg = await program.account.registry.fetch(registryPda);
    expect(reg.authority.equals(wallet)).to.be.true;
    expect(reg.serverKeys).to.have.length(1);
    expect(reg.serverKeys[0].keyId).to.equal(SERVER_KEY_ID);
    expect(Buffer.from(reg.serverKeys[0].pubkey).toString("hex")).to.equal(vectors.serverTestKey.pubkeyHex);
    expect(reg.serverKeys[0].validFrom.toNumber()).to.equal(0);
    expect(reg.serverKeys[0].validTo.toNumber()).to.equal(0);
    expect(reg.partners.map((p) => p.toBase58())).to.deep.equal([wallet.toBase58()]);
    expect(reg.sites.map((s) => s.siteId)).to.deep.equal([1, 2]);
    expect(Buffer.from(reg.sites[0].label).toString("utf8").replace(/\0+$/, "")).to.equal(SITE_1.label);
    expect(Buffer.from(reg.sites[1].label).toString("utf8").replace(/\0+$/, "")).to.equal(SITE_2.label);
  });

  it("registry admin rejects duplicates and non-authority", async () => {
    await expectAnchorError(
      program.methods
        .addServerKey(SERVER_KEY_ID, bytes(serverPubkey), new BN(0), new BN(0))
        .accountsStrict({ registry: registryPda, authority: wallet })
        .rpc(),
      "DuplicateServerKey",
      idlErrors
    );
    await expectAnchorError(
      program.methods.addPartner(wallet).accountsStrict({ registry: registryPda, authority: wallet }).rpc(),
      "DuplicatePartner",
      idlErrors
    );
    await expectAnchorError(
      program.methods
        .addSite(SITE_1.id, label32("dup"))
        .accountsStrict({ registry: registryPda, authority: wallet })
        .rpc(),
      "DuplicateSite",
      idlErrors
    );
    const stranger = Keypair.generate();
    await expectAnchorError(
      program.methods
        .addPartner(stranger.publicKey)
        .accountsStrict({ registry: registryPda, authority: stranger.publicKey })
        .signers([stranger])
        .rpc(),
      "Unauthorized",
      idlErrors
    );
  });

  it("(a) mint passport + attach NECK seal", async () => {
    asset = await createCoreAsset(provider.connection, (provider.wallet as anchor.Wallet).payer);
    await program.methods
      .mintPassport(bytes(serialHash), bytes(bindingHash), asset)
      .accountsStrict({
        registry: registryPda,
        passport: passportPda,
        issuer: wallet,
        systemProgram: SystemProgram.programId,
        coreAsset: asset,
      })
      .rpc();
    const p = await program.account.passport.fetch(passportPda);
    expect(Buffer.from(p.serialHash).toString("hex")).to.equal(scan0.serialHashHex);
    expect(Buffer.from(p.bindingHash).toString("hex")).to.equal(vectors.hashes.binding[0].sha256Hex);
    expect(p.asset.equals(asset)).to.be.true;
    expect(p.issuer.equals(wallet)).to.be.true;
    expect(p.grade).to.equal(G.A);
    expect(p.scanCount).to.equal(0);
    expect(p.sealCount).to.equal(0);
    expect(p.void).to.be.false;
    expect(p.createdAt.toNumber()).to.be.greaterThan(0);

    // kind 2 (LOOP) is reserved
    await expectAnchorError(
      program.methods
        .attachSeal(bytes(uidHash), 2)
        .accountsStrict({
          registry: registryPda,
          passport: passportPda,
          seal: sealPda,
          signer: wallet,
          systemProgram: SystemProgram.programId,
        })
        .rpc(),
      "InvalidSealKind",
      idlErrors
    );

    await program.methods
      .attachSeal(bytes(uidHash), enums.seal_kind.NECK)
      .accountsStrict({
        registry: registryPda,
        passport: passportPda,
        seal: sealPda,
        signer: wallet,
        systemProgram: SystemProgram.programId,
      })
      .rpc();
    const s = await program.account.seal.fetch(sealPda);
    expect(s.passport.equals(passportPda)).to.be.true;
    expect(s.kind).to.equal(enums.seal_kind.NECK);
    expect(Buffer.from(s.uidHash).toString("hex")).to.equal(scan0.uidHashHex);
    expect(s.lastCounter).to.equal(0);
    expect(s.dead).to.be.false;
    expect((await program.account.passport.fetch(passportPda)).sealCount).to.equal(1);
  });

  it("mint/attach by a non-partner fails with NotPartner", async () => {
    const stranger = Keypair.generate();
    const sig = await provider.connection.requestAirdrop(stranger.publicKey, LAMPORTS_PER_SOL);
    await provider.connection.confirmTransaction(sig, "confirmed");
    const otherSerial = hex(vectors.hashes.serial[1].sha256Hex);
    const [otherPassport] = PublicKey.findProgramAddressSync(
      [Buffer.from(SEEDS.passport), otherSerial],
      program.programId
    );
    await expectAnchorError(
      program.methods
        .mintPassport(bytes(otherSerial), bytes(bindingHash), asset)
        .accountsStrict({
          registry: registryPda,
          passport: otherPassport,
          issuer: stranger.publicKey,
          systemProgram: SystemProgram.programId,
          coreAsset: asset,
        })
        .signers([stranger])
        .rpc(),
      "NotPartner",
      idlErrors
    );
    // a non-partner cannot attach a seal to someone else's passport either
    const strayUid = hex(vectors.hashes.uid[1]?.sha256Hex ?? "11".repeat(32));
    const [straySeal] = PublicKey.findProgramAddressSync([Buffer.from(SEEDS.seal), strayUid], program.programId);
    await expectAnchorError(
      program.methods
        .attachSeal(bytes(strayUid), enums.seal_kind.BOX)
        .accountsStrict({ registry: registryPda, passport: passportPda, seal: straySeal, signer: stranger.publicKey, systemProgram: SystemProgram.programId })
        .signers([stranger])
        .rpc(),
      "NotIssuerOrAuthority",
      idlErrors
    );
  });

  it("mint_passport requires a Metaplex Core asset (placeholder pubkeys and mismatched accounts are refused)", async () => {
    const otherSerial = hex(vectors.hashes.serial[1].sha256Hex);
    const [otherPassport] = PublicKey.findProgramAddressSync([Buffer.from(SEEDS.passport), otherSerial], program.programId);
    const mint = (assetArg: PublicKey, coreAsset: PublicKey) =>
      program.methods
        .mintPassport(bytes(otherSerial), bytes(bindingHash), assetArg)
        .accountsStrict({ registry: registryPda, passport: otherPassport, issuer: wallet, systemProgram: SystemProgram.programId, coreAsset })
        .rpc();
    const placeholder = Keypair.generate().publicKey; // no account at all (the old 'Placeholder (localnet)' button)
    await expectAnchorError(mint(placeholder, placeholder), "InvalidAsset", idlErrors);
    // an existing account of another program (a sysvar) is not an asset either
    await expectAnchorError(mint(SYSVAR_RENT_PUBKEY, SYSVAR_RENT_PUBKEY), "InvalidAsset", idlErrors);
    // the account must be the asset named in the arguments
    const real = await createCoreAsset(provider.connection, (provider.wallet as anchor.Wallet).payer);
    await expectAnchorError(mint(placeholder, real), "AssetMismatch", idlErrors);
    expect(await provider.connection.getAccountInfo(otherPassport)).to.be.null;
  });

  it("(b) record_scan without the ed25519 instruction fails", async () => {
    // scans[0] (counter 14) is still unused at this point — only the ed25519 check can fail
    const a = argsFrom(scan0, { ts: new BN(now()) });
    await expectAnchorError(recordScanBuilder(a).rpc(), "MissingEd25519Instruction", idlErrors);
  });

  it("(b') ed25519 instruction signed by a different key fails", async () => {
    const a = argsFrom(scans[1], { ts: new BN(now()) });
    const msg = msgFor(a);
    const other = nacl.sign.keyPair();
    const sig = Buffer.from(nacl.sign.detached(msg, other.secretKey));
    await expectAnchorError(
      recordScanBuilder(a)
        .preInstructions([ed25519Ix(msg, sig, Buffer.from(other.publicKey))])
        .rpc(),
      "ServerKeyMismatch",
      idlErrors
    );
    await expectAnchorError(
      recordScanBuilder({ ...a, serverKeyId: 9 })
        .preInstructions([ed25519Ix(msg, signMessage(msg))])
        .rpc(),
      "UnknownServerKey",
      idlErrors
    );
  });

  it("(b'') the ed25519 instruction must sit right before record_scan and carry its own data", async () => {
    const a = argsFrom(scan0, { ts: new BN(now()) });
    const msg = msgFor(a);
    const ed = ed25519Ix(msg, signMessage(msg));
    // [ed25519, compute budget, record_scan]: not adjacent
    await expectAnchorError(
      recordScanBuilder(a)
        .preInstructions([ed, ComputeBudgetProgram.setComputeUnitLimit({ units: 400_000 })])
        .rpc(),
      "MissingEd25519Instruction",
      idlErrors
    );
    // [ed25519 (inline), ed25519 whose offsets point into instruction 0, record_scan]: the precompile accepts
    // both, but the program only trusts data inside the instruction right before it
    const pointing = Buffer.from(ed.data);
    for (const off of [4, 8, 14]) pointing.writeUInt16LE(0, off); // signature / pubkey / message instruction index = 0
    const pointingIx = new TransactionInstruction({ programId: Ed25519Program.programId, keys: [], data: pointing });
    await expectAnchorError(
      recordScanBuilder(a).preInstructions([ed, pointingIx]).rpc(),
      "MalformedEd25519Instruction",
      idlErrors
    );
  });

  it("(c) same as (a) but fill + 1: message no longer matches", async () => {
    // still before (a): counter 14 unused, so the failure is purely the message check
    const signed = argsFrom(scan0, { ts: new BN(now()) });
    const msg = msgFor(signed);
    const a = { ...signed, fill: scan0.input.fill + 1 };
    await expectAnchorError(
      recordScanBuilder(a)
        .preInstructions([ed25519Ix(msg, signMessage(msg))])
        .rpc(),
      "MessageMismatch",
      idlErrors
    );
  });

  it("(a') the published vector signature for scans[0] is refused as stale (fixed 2026-09 ts)", async () => {
    const a = argsFrom(scan0);
    const msg = msgFor(a);
    expect(msg.toString("hex")).to.equal(scan0.msgHex);
    await expectAnchorError(
      recordScanBuilder(a).preInstructions([ed25519Ix(msg, hex(scan0.sigHex))]).rpc(),
      "StaleScanTimestamp",
      idlErrors
    );
  });

  it("(a) record_scan for scans[0] (same fields, fresh ts, test key)", async () => {
    const ts = now();
    const a = argsFrom(scan0, { ts: new BN(ts) });
    const msg = msgFor(a);
    // identical to the vector message except for the trailing 8-byte ts
    expect(msg.subarray(0, 144).toString("hex")).to.equal(scan0.msgHex.slice(0, 288));

    await recordScanBuilder(a)
      .preInstructions([ed25519Ix(msg, signMessage(msg))])
      .rpc();

    const sp = await program.account.scanProof.fetch(scanPda(scan0.input.counter));
    expect(sp.seal.equals(sealPda)).to.be.true;
    expect(sp.counter).to.equal(14);
    expect(sp.tier).to.equal(scan0.input.tier);
    expect(sp.role).to.equal(scan0.input.role);
    expect(sp.tamper).to.equal(scan0.input.tamper);
    expect(sp.uv).to.equal(scan0.input.uv);
    expect(sp.hum).to.equal(scan0.input.hum);
    expect(sp.heat).to.equal(scan0.input.heat);
    expect(sp.heatLevels).to.equal(scan0.heatMask);
    expect(sp.fill).to.equal(scan0.input.fill);
    expect(sp.siteId).to.equal(0);
    expect(Buffer.from(sp.mediaHash).toString("hex")).to.equal(scan0.input.mediaHashHex);
    expect(Buffer.from(sp.bundleHash).toString("hex")).to.equal(scan0.bundleHashHex);
    expect(sp.attester.equals(wallet)).to.be.true;
    expect(sp.serverKeyId).to.equal(SERVER_KEY_ID);
    expect(sp.ts.toNumber()).to.equal(ts);

    const seal = await program.account.seal.fetch(sealPda);
    expect(seal.lastCounter).to.equal(14);
    const p = await program.account.passport.fetch(passportPda);
    expect(p.grade).to.equal(scan0.grade);
    expect(p.scanCount).to.equal(1);
  });

  it("(d) counter 14 again / counter 13 fail with CounterNotIncreasing", async () => {
    const same = argsFrom(scan0, { ts: new BN(now()) });
    const msgSame = msgFor(same);
    await expectAnchorError(
      recordScanBuilder(same)
        .preInstructions([ed25519Ix(msgSame, signMessage(msgSame))])
        .rpc(),
      "CounterNotIncreasing",
      idlErrors
    );
    const older = argsFrom(scan0, { counter: 13, ts: new BN(now()) });
    const msg = msgFor(older);
    await expectAnchorError(
      recordScanBuilder(older).preInstructions([ed25519Ix(msg, signMessage(msg))]).rpc(),
      "CounterNotIncreasing",
      idlErrors
    );
  });

  it("(e) tier 3 with a non-partner attester fails with NotPartner", async () => {
    const outsider = Keypair.generate();
    const sig = await provider.connection.requestAirdrop(outsider.publicKey, LAMPORTS_PER_SOL);
    await provider.connection.confirmTransaction(sig, "confirmed");

    const a = argsFrom(scan0, { counter: 16, tier: enums.tier.CERTIFIED, role: enums.role.VAULT, ts: new BN(now()) });
    const msg = msgFor(a);
    await expectAnchorError(
      recordScanBuilder(a, outsider.publicKey)
        .preInstructions([ed25519Ix(msg, signMessage(msg))])
        .signers([outsider])
        .rpc(),
      "NotPartner",
      idlErrors
    );

    // SELLER may not attest tier 3 at all
    const b = argsFrom(scan0, { counter: 16, tier: enums.tier.CERTIFIED, role: enums.role.SELLER, ts: new BN(now()) });
    const msgB = msgFor(b);
    await expectAnchorError(
      recordScanBuilder(b).preInstructions([ed25519Ix(msgB, signMessage(msgB))]).rpc(),
      "TierNotAllowedForRole",
      idlErrors
    );

    // site_id only for VAULT/PARTNER
    const c = argsFrom(scan0, { counter: 16, siteId: 1, ts: new BN(now()) });
    const msgC = msgFor(c);
    await expectAnchorError(
      recordScanBuilder(c).preInstructions([ed25519Ix(msgC, signMessage(msgC))]).rpc(),
      "SiteIdNotAllowed",
      idlErrors
    );

    // heat must agree with bit 4 of heat_levels
    const d = argsFrom(scan0, { counter: 16, heat: I.TRIGGERED, ts: new BN(now()) });
    const msgD = msgFor(d);
    await expectAnchorError(
      recordScanBuilder(d).preInstructions([ed25519Ix(msgD, signMessage(msgD))]).rpc(),
      "HeatInconsistent",
      idlErrors
    );
  });

  it("partner tier-3 VAULT scan with site_id and triggered heat → grade C", async () => {
    // scans[1]: heat triggered, counter 15 — as a certified vault scan at site 2
    const a = argsFrom(scans[1], { tier: enums.tier.CERTIFIED, role: enums.role.VAULT, siteId: SITE_2.id, ts: new BN(now()) });
    const msg = msgFor(a);
    await recordScanBuilder(a).preInstructions([ed25519Ix(msg, signMessage(msg))]).rpc();

    const sp = await program.account.scanProof.fetch(scanPda(15));
    expect(sp.siteId).to.equal(SITE_2.id);
    expect(sp.tier).to.equal(enums.tier.CERTIFIED);
    expect(sp.heat).to.equal(I.TRIGGERED);
    expect(sp.heatLevels).to.equal(scans[1].heatMask);
    const p = await program.account.passport.fetch(passportPda);
    expect(p.grade).to.equal(G.C);
    expect(p.grade).to.equal(scans[1].grade);
    expect(p.scanCount).to.equal(2);
    expect((await program.account.seal.fetch(sealPda)).lastCounter).to.equal(15);
  });

  it("C is sticky: a later scan without photo (indicators MISSING, fill 95) keeps grade C", async () => {
    const a = argsFrom(scan0, { counter: 17, heat: I.MISSING, hum: I.MISSING, uv: I.MISSING, heatLevels: 0, fill: 95, ts: new BN(now()) });
    const msg = msgFor(a);
    await recordScanBuilder(a).preInstructions([ed25519Ix(msg, signMessage(msg))]).rpc();
    const p = await program.account.passport.fetch(passportPda);
    expect(p.grade).to.equal(G.C);
    expect(p.void).to.be.false;
    expect(p.scanCount).to.equal(3);
    // the ScanProof itself keeps what this scan saw
    expect((await program.account.scanProof.fetch(scanPda(17))).heat).to.equal(I.MISSING);
  });

  it("(f) mark_seal_dead → further scan fails with SealDead, passport VOID", async () => {
    // a stranger cannot kill the seal
    const stranger = Keypair.generate();
    await airdrop(provider, stranger.publicKey, 1);
    await expectAnchorError(
      program.methods
        .markSealDead()
        .accountsStrict({ registry: registryPda, passport: passportPda, seal: sealPda, signer: stranger.publicKey })
        .signers([stranger])
        .rpc(),
      "NotIssuerOrAuthority",
      idlErrors
    );
    await program.methods
      .markSealDead()
      .accountsStrict({ registry: registryPda, passport: passportPda, seal: sealPda, signer: wallet })
      .rpc();

    const seal = await program.account.seal.fetch(sealPda);
    expect(seal.dead).to.be.true;
    const p = await program.account.passport.fetch(passportPda);
    expect(p.void).to.be.true;
    expect(p.grade).to.equal(G.VOID);
    expect(p.grade).to.equal(4);

    const a = argsFrom(scan0, { counter: 20, ts: new BN(now()) });
    const msg = msgFor(a);
    await expectAnchorError(
      recordScanBuilder(a).preInstructions([ed25519Ix(msg, signMessage(msg))]).rpc(),
      "SealDead",
      idlErrors
    );
    expect((await program.account.passport.fetch(passportPda)).scanCount).to.equal(3);
    // dead stays dead, and a void passport takes no new seal
    await expectAnchorError(
      program.methods.markSealDead().accountsStrict({ registry: registryPda, passport: passportPda, seal: sealPda, signer: wallet }).rpc(),
      "SealDead",
      idlErrors
    );
    const boxUid = sha256(Buffer.from("flacon-test-box-seal-on-void"));
    await expectAnchorError(
      program.methods
        .attachSeal(bytes(boxUid), enums.seal_kind.BOX)
        .accountsStrict({ registry: registryPda, passport: passportPda, seal: sealPdaOf(program.programId, boxUid), signer: wallet, systemProgram: SystemProgram.programId })
        .rpc(),
      "PassportVoid",
      idlErrors
    );
  });

  it("(g) IDL constants equal docs/enums.json and vectors.constants", () => {
    // the client camel-cases IDL names; the raw IDL (as built) keeps SCREAMING_SNAKE
    const rawIdl = (program as any).rawIdl ?? JSON.parse(fs.readFileSync(path.join(ROOT, "target/idl/flacon.json"), "utf8"));
    const consts = (rawIdl.constants ?? []) as { name: string; type: any; value: string }[];
    expect(consts.length).to.be.greaterThan(40);
    const byName = new Map(consts.map((c) => [c.name, c]));
    const constValue = (name: string) => {
      const c = byName.get(name);
      expect(c, `IDL constant ${name}`).to.not.be.undefined;
      return c!.value;
    };
    const constBytes = (name: string): Buffer => {
      const v = constValue(name);
      // byte constants are rendered as `b"..."` or as a JSON array of numbers
      const m = /^b"(.*)"$/.exec(v);
      if (m) return Buffer.from(m[1], "ascii");
      const j = JSON.parse(v);
      if (Array.isArray(j)) return Buffer.from(j);
      return Buffer.from(String(j), "ascii");
    };

    // enums
    for (const [group, values] of Object.entries(enums) as [string, any][]) {
      if (typeof values !== "object" || Array.isArray(values)) continue;
      for (const [key, val] of Object.entries(values as Record<string, number>)) {
        const name = `${group.toUpperCase()}_${key}`;
        expect(constValue(name), name).to.equal(String(val));
      }
    }
    // message + seeds
    expect(constBytes("MSG_PREFIX").toString("ascii")).to.equal(MSG_PREFIX);
    expect(constValue("MSG_LEN")).to.equal(String(MSG_LEN));
    for (const [k, seed] of Object.entries(SEEDS)) {
      expect(constBytes(`${k.toUpperCase()}_SEED`).toString("ascii"), k).to.equal(seed);
    }
    expect(constValue("HEAT_DECISIVE_INDEX")).to.equal(String(vectors.constants.HEAT_DECISIVE_INDEX));
    // grade rule thresholds
    expect(constValue("GRADE_FILL_A_MIN")).to.equal(String(FILL_A_MIN));
    expect(constValue("GRADE_FILL_B_MIN")).to.equal(String(FILL_B_MIN));
    expect(constValue("MAX_SERVER_KEYS")).to.equal("8");
    expect(constValue("MAX_PARTNERS")).to.equal("16");
    expect(constValue("MAX_SITES")).to.equal("16");
    expect(constValue("MAX_SEALS_PER_PASSPORT")).to.equal("2");
    expect(constValue("MAX_SCAN_TS_SKEW_S")).to.equal("600");
    expect(constValue("MAX_COUNTER")).to.equal(String(0xffffff));
  });

  it("(g) grade rule in TS matches vectors.grades (18 rows) and vectors.scans", () => {
    const rows = vectors.grades as any[];
    expect(rows).to.have.length(18);
    for (const r of rows) {
      expect(gradeRule(r), JSON.stringify(r)).to.equal(r.grade);
    }
    for (const s of scans) {
      if (s.input.tamper !== T.UNKNOWN) continue;
      expect(gradeRule(s.input), s.name).to.equal(s.grade);
    }
  });

  // ---------------------------------------------------------------------------
  // Hardening: every case on its own fresh passport (helpers from tests/lib/flacon.ts)
  // ---------------------------------------------------------------------------

  describe("hardening", () => {
    let reg: RegistryHandle;
    const freshPassport = (opts: Parameters<typeof mintPassportWithSeal>[3] = {}) => mintPassportWithSeal(program, registryPda, wallet, opts);
    const admin = () => ({ registry: registryPda, authority: wallet });
    /** next free key_id in the registry */
    const freeKeyId = async () => {
      const r = await program.account.registry.fetch(registryPda);
      const used = new Set(r.serverKeys.map((k) => k.keyId));
      let id = 2;
      while (used.has(id)) id++;
      return id;
    };

    before(async () => {
      reg = await ensureRegistry(program, wallet);
    });

    it("stale and future timestamps are refused (|ts − clock| ≤ 600 s)", async () => {
      const p = await freshPassport();
      const t = await chainTime(provider.connection);
      for (const ts of [t - 700, t + 700]) {
        await expectAnchorError(buildScan(program, provider, reg, p, { counter: 1, fill: 95, ts }).rpc(), "StaleScanTimestamp", idlErrors);
      }
      await recordScan(program, provider, reg, p, { counter: 1, fill: 95, ts: t - 500 });
      await recordScan(program, provider, reg, p, { counter: 2, fill: 95, ts: t + 300 });
    });

    it("counters above the 24-bit NTAG range are refused", async () => {
      const p = await freshPassport();
      await expectAnchorError(buildScan(program, provider, reg, p, { counter: 0x1000000, fill: 95 }).rpc(), "CounterOutOfRange", idlErrors);
      await recordScan(program, provider, reg, p, { counter: 0xffffff, fill: 95 });
      expect((await program.account.seal.fetch(p.sealPda)).lastCounter).to.equal(0xffffff);
    });

    it("server keys outside their validity window are refused", async () => {
      const p = await freshPassport();
      const t = await chainTime(provider.connection);
      const expired = await freeKeyId();
      await program.methods.addServerKey(expired, bytes(serverPubkey), new BN(0), new BN(1000)).accountsStrict(admin()).rpc();
      await expectAnchorError(
        buildScan(program, provider, reg, p, { counter: 1, fill: 95, serverKeyId: expired }).rpc(),
        "ServerKeyNotValidAtTs",
        idlErrors
      );
      const future = await freeKeyId();
      await program.methods.addServerKey(future, bytes(serverPubkey), new BN(t + 86400), new BN(0)).accountsStrict(admin()).rpc();
      await expectAnchorError(
        buildScan(program, provider, reg, p, { counter: 1, fill: 95, serverKeyId: future }).rpc(),
        "ServerKeyNotValidAtTs",
        idlErrors
      );
      // tidy up: both keys end now
      await program.methods.revokeServerKey(future).accountsStrict(admin()).rpc();
      await expectAnchorError(program.methods.revokeServerKey(expired).accountsStrict(admin()).rpc(), "ServerKeyAlreadyRevoked", idlErrors);
    });

    it("revoke_server_key: authority only; takes effect at once, even for signatures dated before the revocation", async () => {
      const p = await freshPassport();
      const id = await freeKeyId();
      await program.methods.addServerKey(id, bytes(serverPubkey), new BN(0), new BN(0)).accountsStrict(admin()).rpc();
      await recordScan(program, provider, reg, p, { counter: 1, fill: 95, serverKeyId: id });
      // signed (dated) a minute before the revocation, sent after it
      const t = await chainTime(provider.connection);
      const pending = buildScan(program, provider, reg, p, { counter: 2, fill: 95, serverKeyId: id, ts: t - 60 });

      const stranger = Keypair.generate();
      await expectAnchorError(
        program.methods.revokeServerKey(id).accountsStrict({ registry: registryPda, authority: stranger.publicKey }).signers([stranger]).rpc(),
        "Unauthorized",
        idlErrors
      );
      await expectAnchorError(program.methods.revokeServerKey(250).accountsStrict(admin()).rpc(), "UnknownServerKey", idlErrors);
      await program.methods.revokeServerKey(id).accountsStrict(admin()).rpc();
      const k = (await program.account.registry.fetch(registryPda)).serverKeys.find((x) => x.keyId === id)!;
      expect(k.validTo.toNumber()).to.be.greaterThan(0);
      expect(k.validTo.toNumber()).to.be.lessThan((await chainTime(provider.connection)) + 1);

      await expectAnchorError(pending.rpc(), "ServerKeyNotValidNow", idlErrors);
      await expectAnchorError(buildScan(program, provider, reg, p, { counter: 3, fill: 95, serverKeyId: id }).rpc(), "ServerKeyNotValidAtTs", idlErrors);
      await expectAnchorError(program.methods.revokeServerKey(id).accountsStrict(admin()).rpc(), "ServerKeyAlreadyRevoked", idlErrors);
      // the key_id stays taken
      await expectAnchorError(
        program.methods.addServerKey(id, bytes(serverPubkey), new BN(0), new BN(0)).accountsStrict(admin()).rpc(),
        "DuplicateServerKey",
        idlErrors
      );
      // the main test key still works
      await recordScan(program, provider, reg, p, { counter: 4, fill: 95 });
    });

    it("SealPassportMismatch: a seal of passport B cannot be scanned into passport A", async () => {
      const a = await freshPassport();
      const b = await freshPassport();
      // message bound to A's serial and B's seal: the reconstruction matches, the seal check does not
      await expectAnchorError(
        buildScan(program, provider, reg, { ...a, uidHash: b.uidHash, sealPda: b.sealPda }, { counter: 1, fill: 95 }).rpc(),
        "SealPassportMismatch",
        idlErrors
      );
    });

    it("second seal: one BOX next to the NECK, scans on both, a third seal is refused", async () => {
      const p = await freshPassport({ kind: enums.seal_kind.NECK });
      const boxUid = sha256(Buffer.from(`box-${p.serial}`));
      const boxSeal = sealPdaOf(program.programId, boxUid);
      await program.methods
        .attachSeal(bytes(boxUid), enums.seal_kind.BOX)
        .accountsStrict({ registry: registryPda, passport: p.passportPda, seal: boxSeal, signer: wallet, systemProgram: SystemProgram.programId })
        .rpc();
      const pp = await program.account.passport.fetch(p.passportPda);
      expect(pp.sealCount).to.equal(2);
      expect((await program.account.seal.fetch(boxSeal)).kind).to.equal(enums.seal_kind.BOX);

      const box = { ...p, uidHash: boxUid, sealPda: boxSeal };
      await recordScan(program, provider, reg, box, { counter: 1, fill: 95 });
      await recordScan(program, provider, reg, p, { counter: 1, fill: 95 });
      expect((await program.account.passport.fetch(p.passportPda)).scanCount).to.equal(2);
      expect((await program.account.scanProof.fetch(scanPdaOf(program.programId, boxSeal, 1))).seal.equals(boxSeal)).to.be.true;

      const thirdUid = sha256(Buffer.from(`third-${p.serial}`));
      await expectAnchorError(
        program.methods
          .attachSeal(bytes(thirdUid), enums.seal_kind.BOX)
          .accountsStrict({ registry: registryPda, passport: p.passportPda, seal: sealPdaOf(program.programId, thirdUid), signer: wallet, systemProgram: SystemProgram.programId })
          .rpc(),
        "TooManySeals",
        idlErrors
      );
    });

    it("grade only worsens: C then a MISSING-indicator scan stays C, low fill moves on to D", async () => {
      const p = await freshPassport();
      await recordScan(program, provider, reg, p, { counter: 1, fill: 95, heat: I.TRIGGERED, heatLevels: 0b010000 });
      expect((await program.account.passport.fetch(p.passportPda)).grade).to.equal(G.C);
      await recordScan(program, provider, reg, p, { counter: 2, fill: 95, heat: I.MISSING, hum: I.MISSING });
      expect((await program.account.passport.fetch(p.passportPda)).grade).to.equal(G.C);
      await recordScan(program, provider, reg, p, { counter: 3, fill: 95, heat: I.UNREADABLE, hum: I.INTACT });
      expect((await program.account.passport.fetch(p.passportPda)).grade).to.equal(G.C);
      await recordScan(program, provider, reg, p, { counter: 4, fill: 40 });
      expect((await program.account.passport.fetch(p.passportPda)).grade).to.equal(G.D);
      await recordScan(program, provider, reg, p, { counter: 5, fill: 100 });
      const pp = await program.account.passport.fetch(p.passportPda);
      expect(pp.grade).to.equal(G.D);
      expect(pp.void).to.be.false;
    });

    it("an opened seal (tamper OPENED_NOW / OPENED_BEFORE) voids the passport for good", async () => {
      for (const tamper of [T.OPENED_NOW, T.OPENED_BEFORE]) {
        const p = await freshPassport();
        await recordScan(program, provider, reg, p, { counter: 1, fill: 95, tamper });
        const pp = await program.account.passport.fetch(p.passportPda);
        expect(pp.grade).to.equal(G.VOID);
        expect(pp.void).to.be.true;
        await expectAnchorError(buildScan(program, provider, reg, p, { counter: 2, fill: 100, tamper: T.CLOSED }).rpc(), "PassportVoid", idlErrors);
        const boxUid = sha256(Buffer.from(`box-on-void-${p.serial}`));
        await expectAnchorError(
          program.methods
            .attachSeal(bytes(boxUid), enums.seal_kind.BOX)
            .accountsStrict({ registry: registryPda, passport: p.passportPda, seal: sealPdaOf(program.programId, boxUid), signer: wallet, systemProgram: SystemProgram.programId })
            .rpc(),
          "PassportVoid",
          idlErrors
        );
      }
    });

    it("remove_partner: the removed partner loses mint and seal rights; another partner never had them on foreign passports", async () => {
      const partner = Keypair.generate();
      const other = Keypair.generate();
      await airdrop(provider, partner.publicKey, 2);
      await airdrop(provider, other.publicKey, 2);
      await program.methods.addPartner(partner.publicKey).accountsStrict(admin()).rpc();
      await program.methods.addPartner(other.publicKey).accountsStrict(admin()).rpc();
      const p = await freshPassport({ issuer: partner });
      expect((await program.account.passport.fetch(p.passportPda)).issuer.equals(partner.publicKey)).to.be.true;

      // a different partner may not attach seals to / kill seals of the partner's passport
      const boxUid = sha256(Buffer.from(`box-${p.serial}`));
      const boxSeal = sealPdaOf(program.programId, boxUid);
      const attach = (signer: Keypair | null) => {
        const b = program.methods
          .attachSeal(bytes(boxUid), enums.seal_kind.BOX)
          .accountsStrict({ registry: registryPda, passport: p.passportPda, seal: boxSeal, signer: signer?.publicKey ?? wallet, systemProgram: SystemProgram.programId });
        return signer ? b.signers([signer]) : b;
      };
      const kill = (signer: Keypair | null) => {
        const b = program.methods
          .markSealDead()
          .accountsStrict({ registry: registryPda, passport: p.passportPda, seal: p.sealPda, signer: signer?.publicKey ?? wallet });
        return signer ? b.signers([signer]) : b;
      };
      await expectAnchorError(attach(other).rpc(), "NotIssuerOrAuthority", idlErrors);
      await expectAnchorError(kill(other).rpc(), "NotIssuerOrAuthority", idlErrors);

      // remove: non-authority refused, unknown partner refused
      await expectAnchorError(
        program.methods.removePartner(partner.publicKey).accountsStrict({ registry: registryPda, authority: other.publicKey }).signers([other]).rpc(),
        "Unauthorized",
        idlErrors
      );
      await program.methods.removePartner(partner.publicKey).accountsStrict(admin()).rpc();
      await expectAnchorError(program.methods.removePartner(partner.publicKey).accountsStrict(admin()).rpc(), "PartnerNotFound", idlErrors);
      expect((await program.account.registry.fetch(registryPda)).partners.some((x) => x.equals(partner.publicKey))).to.be.false;

      await expectAnchorError(attach(partner).rpc(), "NotIssuerOrAuthority", idlErrors);
      await expectAnchorError(kill(partner).rpc(), "NotIssuerOrAuthority", idlErrors);
      await expectAnchorError(freshPassport({ issuer: partner }), "NotPartner", idlErrors);
      // the registry authority still can
      await attach(null).rpc();
      await kill(null).rpc();
      expect((await program.account.passport.fetch(p.passportPda)).void).to.be.true;
      await program.methods.removePartner(other.publicKey).accountsStrict(admin()).rpc();
    });

    it("transfer_authority: the new authority must co-sign; the old one loses its rights", async () => {
      const next = Keypair.generate();
      await airdrop(provider, next.publicKey, 1);
      const stranger = Keypair.generate();
      await expectAnchorError(
        program.methods
          .transferAuthority()
          .accountsStrict({ registry: registryPda, authority: stranger.publicKey, newAuthority: next.publicKey })
          .signers([stranger, next])
          .rpc(),
        "Unauthorized",
        idlErrors
      );
      await program.methods
        .transferAuthority()
        .accountsStrict({ registry: registryPda, authority: wallet, newAuthority: next.publicKey })
        .signers([next])
        .rpc();
      expect((await program.account.registry.fetch(registryPda)).authority.equals(next.publicKey)).to.be.true;
      await expectAnchorError(program.methods.addPartner(Keypair.generate().publicKey).accountsStrict(admin()).rpc(), "Unauthorized", idlErrors);
      // hand it back (both sign again)
      await program.methods
        .transferAuthority()
        .accountsStrict({ registry: registryPda, authority: next.publicKey, newAuthority: wallet })
        .signers([next])
        .rpc();
      expect((await program.account.registry.fetch(registryPda)).authority.equals(wallet)).to.be.true;
    });

    it("every accepted scan counts in scan_count, whatever its tier (stats.onChainScanCount contract)", async () => {
      const p = await freshPassport();
      await recordScan(program, provider, reg, p, { counter: 1, fill: 95, tier: enums.tier.SELF, role: enums.role.OWNER });
      await recordScan(program, provider, reg, p, { counter: 2, fill: 95, tier: enums.tier.SELF_MEDIA, role: enums.role.OWNER });
      await recordScan(program, provider, reg, p, { counter: 3, fill: 95, tier: enums.tier.CERTIFIED, role: enums.role.VAULT, siteId: SITE_1.id });
      expect((await program.account.passport.fetch(p.passportPda)).scanCount).to.equal(3);
      // a scan args/message pair from the lib helper matches the program's reconstruction
      const { msg } = scanArgs(reg, p, { counter: 9, fill: 1 });
      expect(msg.length).to.equal(MSG_LEN);
    });
  });
});
